-- PixelRP: the Modern Hospital set, in Builders > Corporations > Hospital.
--
-- 60 pieces on ONE page under the existing Corporations category, beside
-- the Corporation Gate 146 put there. Generated by
-- docker/nitro/import-pack-tree.py.
--
-- A flat page rather than subcategories because the download is flat: sixty
-- bundles of one set, with nothing in it that groups them.
--
-- The pack carries no names - its manifest records each item's classname and
-- nothing else - so the titles are the set's own name and the number the
-- bundle already had: 'Modern Hospital 01' through 60. Derived, not invented;
-- there is nothing in the download that says which one is the bed.
--
-- The rendering half is the .nitro bundles, the icons and the FurnitureData
-- entries under nitro/overrides/; the rows below are inert without them.
--
-- Everything is free - the catalog has been since 90_FreeCatalog.
--
-- Idempotent: fixed id ranges, cleared before insert. Hospital is the only page in its range.

SET @builders := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `caption` = 'Builders' LIMIT 1),
    912362);
SET @corps := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = @builders AND `caption` = 'Corporations' LIMIT 1),
    @builders);

DELETE FROM `catalog_items` WHERE `item_id` BETWEEN 110400 AND 110459;
DELETE FROM `catalog_pages` WHERE `id` BETWEEN 950000 AND 950999;
DELETE FROM `furniture` WHERE `id` BETWEEN 110400 AND 110459;

     `page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`)
VALUES
    (950000, @corps, 'Hospital', 193, 2, 0, 1, '', 'default_3x3', '', '', b'1', b'1');


-- Furniture. id == sprite_id, the convention every custom line here follows;
-- interaction_modes_count is the bundle's own animation count.

